// Nonroot, key-free, isolated PostgreSQL+uploads disposal phase.
// Only an immutable owner-approved local image is permitted.
export const RESTORE_PY="\"\"\"Exact 4C9 P520 restoration. Runs only as nonroot inside private networkless container.\"\"\"\nimport hashlib\nimport io\nimport os\nfrom pathlib import Path, PurePosixPath\nimport re\nimport subprocess\nimport sys\nimport tarfile\n\nARCHIVE=Path(\"/recovery/bundle.tar.gz\")\nDUMP=Path(\"/tmp/kmj-database.dump\")\nSTORAGE=Path(\"/tmp/kmj-uploads\")\nPGDATA=Path(\"/tmp/kmj-pgdata\")\nMAX_DB=256*1024*1024\nMAX_STORAGE=384*1024*1024\nMAX_TOTAL=640*1024*1024\nMAX_FILES=20000\n\ndef block(reason):\n    raise ValueError(\"BLOCKED_\"+reason)\n\ndef run(argv,timeout=300):\n    return subprocess.run(argv,check=True,timeout=timeout,\n        stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)\n\ndef archive_check(archive,source):\n    members=archive.getmembers()\n    required={\"database.dump\",\"storage.tar.gz\",\"metadata.txt\",\"SHA256SUMS\"}\n    if len(members)!=4 or {m.name for m in members}!=required:\n        block(\"BUNDLE_MEMBERS\")\n    if any(not m.isfile() or m.size<=0 for m in members):\n        block(\"BUNDLE_MEMBER_TYPE\")\n    by_name={m.name:m for m in members}\n    if by_name[\"database.dump\"].size>MAX_DB or by_name[\"storage.tar.gz\"].size>MAX_STORAGE:\n        block(\"BUNDLE_SIZE\")\n    if sum(m.size for m in members)>MAX_TOTAL:\n        block(\"BUNDLE_TOTAL_SIZE\")\n    for name in [\"metadata.txt\",\"SHA256SUMS\"]:\n        if by_name[name].size>16384:block(\"METADATA_SIZE\")\n    small={}\n    for name in [\"metadata.txt\",\"SHA256SUMS\"]:\n        f=archive.extractfile(by_name[name])\n        if f is None:block(\"METADATA_UNREADABLE\")\n        small[name]=f.read(16385).decode(\"ascii\")\n        if len(small[name])>16384:block(\"METADATA_LIMIT\")\n    pairs={}\n    for line in small[\"SHA256SUMS\"].splitlines():\n        m=re.fullmatch(r\"([a-f0-9]{64})  (database\\.dump|storage\\.tar\\.gz|metadata\\.txt)\",line)\n        if not m or m.group(2) in pairs:block(\"MANIFEST\")\n        pairs[m.group(2)]=m.group(1)\n    if set(pairs)!={\"database.dump\",\"storage.tar.gz\",\"metadata.txt\"}:\n        block(\"MANIFEST_FILENAMES\")\n    metadata={}\n    for line in small[\"metadata.txt\"].splitlines():\n        key,sep,val=line.partition(\"=\")\n        if not sep or key in metadata:block(\"METADATA\")\n        metadata[key]=val\n    expected={\n      \"backup_kind\":\"offsite_sanitized_local_witness\",\n      \"source_local_sha256\":source,\n      \"target_sha\":\"4c9d59103b99a6cfe675bb7b8961fc956eb294f0\",\n      \"current_release\":\"platform-ce6ad7dc9d89\",\n      \"production_env_excluded\":\"YES\"\n    }\n    if metadata!=expected:block(\"RECOVERY_IDENTITY\")\n    if hashlib.sha256(small[\"metadata.txt\"].encode(\"ascii\")).hexdigest()!=pairs[\"metadata.txt\"]:\n        block(\"METADATA_SHA\")\n    return by_name,pairs\n\ndef copy_dump(archive,member,sha):\n    f=archive.extractfile(member)\n    if f is None:block(\"DUMP_UNREADABLE\")\n    h=hashlib.sha256()\n    written=0\n    with open(DUMP,\"xb\") as output:\n        while written<member.size:\n            chunk=f.read(min(1024*1024,member.size-written))\n            if not chunk:block(\"DUMP_TRUNCATED\")\n            h.update(chunk)\n            output.write(chunk)\n            written+=len(chunk)\n    if written!=member.size or h.hexdigest()!=sha:\n        block(\"DUMP_DIGEST\")\n    with open(DUMP,\"rb\") as data:\n        if data.read(5)!=b\"PGDMP\":block(\"DUMP_MAGIC\")\n\ndef copy_storage(archive,member,sha):\n    f=archive.extractfile(member)\n    if f is None:block(\"STORAGE_UNREADABLE\")\n    h=hashlib.sha256()\n    # Revalidate actual compressed bytes prior to extraction; no key is mounted.\n    compressed=Path(\"/tmp/kmj-storage.tar.gz\")\n    copied=0\n    with open(compressed,\"xb\") as target:\n        while copied<member.size:\n            chunk=f.read(min(1024*1024,member.size-copied))\n            if not chunk:block(\"STORAGE_TRUNCATED\")\n            copied+=len(chunk)\n            h.update(chunk)\n            target.write(chunk)\n    if copied!=member.size or h.hexdigest()!=sha:block(\"STORAGE_SHA\")\n    STORAGE.mkdir(mode=0o700)\n    seen=set()\n    nfiles=0\n    nbytes=0\n    with tarfile.open(compressed,\"r:gz\") as inner:\n        for entry in inner:\n            name=PurePosixPath(entry.name)\n            key=name.as_posix()\n            if (entry.size<0 or key in seen or name.is_absolute() or\n                \"..\" in name.parts or name.parts[:2]!=(\"storage\",\"app\") or\n                \"\\\\\" in entry.name or entry.sparse is not None or\n                any(x.lower()==\".env\" or x.lower().startswith(\".env.\") for x in name.parts) or\n                not (entry.isfile() or entry.isdir())):\n                block(\"UNSAFE_STORAGE_ENTRY\")\n            seen.add(key)\n            nbytes+=entry.size\n            if len(seen)>MAX_FILES or nbytes>MAX_STORAGE:block(\"STORAGE_BOUNDS\")\n            dest=STORAGE.joinpath(*name.parts)\n            if entry.isdir():\n                dest.mkdir(parents=True,mode=0o700,exist_ok=True)\n                continue\n            dest.parent.mkdir(parents=True,mode=0o700,exist_ok=True)\n            reader=inner.extractfile(entry)\n            if reader is None:block(\"STORAGE_FILE_UNREADABLE\")\n            source_hash=hashlib.sha256()\n            copied=0\n            with open(dest,\"xb\") as output:\n                os.chmod(dest,0o600)\n                while copied<entry.size:\n                    chunk=reader.read(min(1024*1024,entry.size-copied))\n                    if not chunk:block(\"STORAGE_FILE_TRUNCATED\")\n                    source_hash.update(chunk)\n                    output.write(chunk)\n                    copied+=len(chunk)\n            if copied!=entry.size:block(\"STORAGE_FILE_SIZE\")\n            restored_hash=hashlib.sha256()\n            with open(dest,\"rb\") as new_file:\n                for chunk in iter(lambda:new_file.read(1024*1024),b\"\"):\n                    restored_hash.update(chunk)\n            if restored_hash.digest()!=source_hash.digest():\n                block(\"STORAGE_RESTORED_PARITY\")\n            nfiles+=1\n    if nfiles<1:block(\"EMPTY_STORAGE\")\n    return nfiles\n\ndef recover_postgres():\n    if os.geteuid()==0:block(\"ROOT_PG_EXECUTION\")\n    if os.environ.get(\"KMJ_P520_NETWORKLESS\")!=\"1\":block(\"MISSING_ISOLATION_MARKER\")\n    run([\"initdb\",\"-D\",str(PGDATA),\"-U\",\"postgres\",\n         \"--auth-local=trust\",\"--auth-host=reject\",\"-E\",\"UTF8\"],timeout=120)\n    conf=PGDATA/\"postgresql.conf\"\n    with conf.open(\"a\",encoding=\"ascii\") as out:\n        out.write(\"\\nlisten_addresses = ''\\n\")\n        out.write(\"unix_socket_directories = '/tmp'\\n\")\n        out.write(\"port = 55432\\nfsync = off\\nshared_buffers = '32MB'\\n\")\n    started=False\n    try:\n        run([\"pg_ctl\",\"-D\",str(PGDATA),\"-w\",\"-t\",\"60\",\"start\",\n             \"-l\",\"/tmp/kmj-pg.log\"],timeout=90)\n        started=True\n        run([\"pg_restore\",\"-h\",\"/tmp\",\"-p\",\"55432\",\"-U\",\"postgres\",\n             \"-d\",\"postgres\",\"--exit-on-error\",\"--single-transaction\",\n             \"--no-owner\",\"--no-privileges\",str(DUMP)],timeout=600)\n        sql=(\"select count(*) from pg_catalog.pg_class c \"\n             \"join pg_catalog.pg_namespace n on n.oid=c.relnamespace \"\n             \"where c.relkind='r' and n.nspname not in \"\n             \"('pg_catalog','information_schema') \"\n             \"and n.nspname not like 'pg_toast%';\")\n        result=subprocess.run([\"psql\",\"-X\",\"-A\",\"-t\",\"-h\",\"/tmp\",\"-p\",\"55432\",\n            \"-U\",\"postgres\",\"-d\",\"postgres\",\"-v\",\"ON_ERROR_STOP=1\",\"-c\",sql],\n            check=True,capture_output=True,text=True,timeout=30)\n        count=int(result.stdout.strip())\n        if count<1:block(\"NO_RESTORED_TABLES\")\n        # Reject schema-only or empty migration-table dumps. A restored Laravel\n        # application must have at least one recorded migration batch.\n        migrated=subprocess.run([\"psql\",\"-X\",\"-A\",\"-t\",\"-h\",\"/tmp\",\"-p\",\"55432\",\n            \"-U\",\"postgres\",\"-d\",\"postgres\",\"-v\",\"ON_ERROR_STOP=1\",\n            \"-c\",\"SELECT count(*) FROM public.migrations;\"],\n            check=True,capture_output=True,text=True,timeout=30)\n        if int(migrated.stdout.strip())<1:block(\"NO_RESTORED_MIGRATIONS\")\n        return count\n    finally:\n        if started:\n            run([\"pg_ctl\",\"-D\",str(PGDATA),\"-m\",\"immediate\",\"-w\",\"stop\"],timeout=60)\n\ndef main():\n    if len(sys.argv)!=2 or not re.fullmatch(\"[a-f0-9]{64}\",sys.argv[1]):\n        block(\"EXACT_SOURCE_DIGEST_ARG\")\n    if not ARCHIVE.is_file():block(\"MISSING_PLAINTEXT_BUNDLE\")\n    if os.geteuid()==0:block(\"ROOT_CONTAINER_USER\")\n    with tarfile.open(ARCHIVE,\"r:gz\") as archive:\n        members,manifest=archive_check(archive,sys.argv[1])\n        copy_dump(archive,members[\"database.dump\"],manifest[\"database.dump\"])\n        nfiles=copy_storage(archive,members[\"storage.tar.gz\"],manifest[\"storage.tar.gz\"])\n    tables=recover_postgres()\n    if nfiles<1 or tables<1:block(\"INCOMPLETE_RESTORE\")\n    print(\"KMJ_P520_DISPOSABLE_PG_STORAGE=PASS\")\n\nif __name__==\"__main__\":\n    try:\n        main()\n    except Exception:\n        print(\"KMJ_P520_DISPOSABLE_PG_STORAGE=BLOCKED\",file=sys.stderr)\n        sys.exit(2)\n";
const SHA=/^[0-9a-f]{64}$/;
export function pgStorageArgs(volume,image,source){
  if(!/^kmj-p520-verify-[a-f0-9]{32}$/.test(volume) ||
      !SHA.test(image) || !SHA.test(source))throw Error('UNPINNED_RECOVERY_INPUT');
  return ['run','--rm','--pull=never','--network=none','--read-only',
    '--cap-drop=ALL','--security-opt=no-new-privileges','--user=postgres',
    '--pids-limit=128','--cpus=1','--memory=2048m',
    '--tmpfs=/tmp:rw,nosuid,nodev,size=1024m,mode=1777',
    '--mount=type=volume,src='+volume+',dst=/recovery,readonly',
    '--env=KMJ_P520_NETWORKLESS=1',
    '--entrypoint=python3','sha256:'+image,'-c',RESTORE_PY,source];
}
